    rank 1 和 rank 2 正文逐字相同（G1 / S1 各一份），实际只覆盖两个知识点。
    保留哪一条交给 rerank 决定——它的输入带 product 与面包屑，问 S1 时 S1 那份分更高。
    """
    kept: list[dict] = []
    index_by_key: dict[str, int] = {}
    for chunk, score in ranked:
        cite_version = _citation_version(chunk, requested)
        key = _content_key(chunk)
        if key and key in index_by_key:
            kept[index_by_key[key]]["alt_sources"].append(_alt_source(chunk, cite_version))
            continue
        if key:
            index_by_key[key] = len(kept)
        kept.append(
            {
                "chunk": chunk,
                "score": score,
                "cite_version": cite_version,
                "alt_sources": [],
            }
        )
    return kept

